Compare `Blob` objects
```ts
import { assertEquals } from "@ende/assert";

const bytes1 = await new Blob(["foo"]).bytes();
const bytes2 = await new Blob(["foo"]).bytes();

assertEquals(bytes1, bytes2);
```

Usage
```ts ignore
import { assertStrictEquals } from "@ende/assert";

const a = {};
const b = a;
assertStrictEquals(a, b); // Doesn't throw

const c = {};
const d = {};
assertStrictEquals(c, d); // Throws
```

Usage
```ts
import { AssertionError } from "@ende/assert";

try {
  throw new AssertionError("foo", { cause: "bar" });
} catch (error) {
  if (error instanceof AssertionError) {
    error.message === "foo"; // true
    error.cause === "bar"; // true
  }
}
```

