Exhaustivenss check
```ts
import { assertNever } from "@ende/assert/unstable-never";

type Kinds = "A" | "B";

function handleKind(kind: Kinds) {
  switch (kind) {
    case "A":
      doA();
      break;
    case "B":
      doB();
      break;
    default:
      assertNever(kind);
  }
}

function doA() {
  // ...
}

function doB() {
  // ...
}
```

Compile-time error when there is a missing case
```ts expect-error ignore
import { assertNever } from "@ende/assert/unstable-never";

type Kinds = "A" | "B" | "C";

function handleKind(kind: Kinds) {
  switch (kind) {
    case "A":
      doA();
      break;
    case "B":
      doB();
      break;
    default:
      // Type error since "C" is not handled
      assertNever(kind);
  }
}

function doA() {
  // ...
}

function doB() {
  // ...
}
```

